//! Ports of the `roaring` 0.11.5 test suite to `RoaringBitmap128`.
//!
//! One module per original file:
//!
//! * `bitmap_<name>` ports `tests/<name>.rs` (written for `RoaringBitmap`, `u32`),
//! * `treemap_<name>` ports `tests/treemap_<name>.rs` (`RoaringTreemap`, `u64`),
//! * `src_<path>` ports the in-source unit tests and proptests of `src/<path>.rs`.
//!
//! Tests generated by `offset_variants!` are modules with one test per offset: `<test>::orig` is
//! the faithful port (offset 0), the other cases run the same body at 128-bit offsets (around
//! 2^32, 2^64, 2^100, 2^112 and near `u128::MAX`, aligned and unaligned to container keys).
//! Hand written 128-bit variants carry a `_u128` / `_2p64` / `_max` suffix.
//!
//! The following originals are identical to their bitmap counterpart (modulo the type and the
//! formatting) and are therefore covered by the `bitmap_*` module of the same name:
//! `treemap_clone.rs`, `treemap_difference_with.rs`, `treemap_intersect_with.rs`,
//! `treemap_is_disjoint.rs`, `treemap_is_subset.rs`, `treemap_size_hint.rs`,
//! `treemap_symmetric_difference_with.rs`, `treemap_union_with.rs`.
//! `tests/serialization.rs`, `tests/treemap_serialization.rs` and the serialization related
//! in-source tests are ported in the `serialization` test binary.

#[macro_use]
#[path = "../common/mod.rs"]
mod common;

mod bitmap_clone;
mod bitmap_difference_with;
mod bitmap_intersect_with;
mod bitmap_is_disjoint;
mod bitmap_is_subset;
mod bitmap_iter;
mod bitmap_iter_advance_to;
mod bitmap_iter_next_range;
mod bitmap_iter_range;
mod bitmap_lib;
mod bitmap_ops;
mod bitmap_push;
mod bitmap_range_checks;
mod bitmap_rank;
mod bitmap_select;
mod bitmap_size_hint;
mod bitmap_symmetric_difference_with;
mod bitmap_union_with;

mod treemap_iter;
mod treemap_iter_advance_to;
mod treemap_lib;
mod treemap_ops;
mod treemap_range_checks;
mod treemap_rank;
mod treemap_select;

mod src_bitmap_inherent;
mod src_bitmap_ops;
mod src_bitmap_proptests;
mod src_bitmap_statistics;
mod src_treemap_inherent;
